    // Initialize a visited array to keep track of the n-tersections that have been visited
    boolean[][] visited = new boolean[n][n];

    // Initialize a queue to perform BFS
    Queue<int[]> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]][start[1]] = true;
    queue.offer(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current n-tersection and its coordinates
        int[] current = queue.poll();
        int x = current[0];
        int y = current[1];

        // If the current n-tersection is the ending n-tersection, return "can be travelled"
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Check if the current n-tersection has any paths to adjacent n-tersections
        if (paths[x][y] != null) {
            // Loop through all possible paths from the current n-tersection
            for (int i = 0; i < paths[x][y].length; i++) {
                // Get the coordinates of the adjacent n-tersection
                int adjX = paths[x][y][i][0];
                int adjY = paths[x][y][i][1];

                // If the adjacent n-tersection has not been visited, mark it as visited and add it to the queue
                if (!visited[adjX][adjY]) {
