public class ZigzagTraversal {

    public List<List<Integer>> zigzagLevelOrder(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }
        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);
        boolean leftToRight = true;

        while (!queue.isEmpty()) {
            LinkedList<Integer> level = new LinkedList<>();
            int levelSize = queue.size();
            for (int i = 0; i < levelSize; i++) {
                TreeNode currentNode = queue.poll();
                if (leftToRight) {
                    level.addLast(currentNode.val);
                } else {
                    level.addFirst(currentNode.val);
                }
                if (currentNode.left != null) {
                    queue.offer(currentNode.left);
                }
                if (currentNode.right != null) {
                    queue.offer(currentNode.right);
                }
            }
            result.add(level);
            leftToRight = !leftToRight;
        }
        return result;
    }

    public static void main(String[] args) {
        ZigzagTraversal traversal = new ZigzagTraversal();
        TreeNode root = traversal.new TreeNode(3);
        root.left = traversal.new TreeNode(9);
        root.right = traversal.new TreeNode(20);
        root.right.left = traversal.new TreeNode(15);
        root.right.right = traversal.new TreeNode(7);

        List<List<Integer>> zigzagOrder = traversal.zigzagLevelOrder(root);
        System.out.println(zigzagOrder); // Expected output: [[3], [20, 9], [15, 7]]
