public boolean splitArraySameAverage(int[] nums) {
    // find the sum of all the integers in the array
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    // set the target sum to half of the total sum
    int target = sum / 2;

    // create a 2D dp table to store the results of the previous i integers
    boolean[][] dp = new boolean[nums.length + 1][target + 1];

    // initialize the first row of the dp table to true, since we can always partition an empty array
    dp[0][0] = true;

    // loop through the input array
    for (int i = 1; i <= nums.length; i++) {
        int num = nums[i - 1];

        // loop through the previous i integers
        for (int j = 0; j <= target; j++) {
            // if we can partition the previous i - 1 integers such that the sum of the integers in one partition is equal to j, and the sum of the integers in the other partition is equal to j - num, then we can also partition the previous i integers such that the sum of the integers in one partition is equal to j + num, and the sum of the integers in the other partition is equal to j - num + num
            dp[i][j] = dp[i - 1][j] || (j >= num && dp[i - 1][j - num]);
        }
    }

    // return the answer as dp[n][sum/2]
    return dp[nums.length][target];
}
