public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (cost[0] == 0) {
        return minCostClimbingStairs(cost, 1, new int[n]);
    }
    return Math.min(cost[0], minCostClimbingStairs(cost, 1, new int[n]));
}

private static int minCostClimbingStairs(int[] cost, int index, int[] dp) {
    if (index >= cost.length) {
        return 0;
    }
    if (dp[index] > 0) {
        return dp[index];
    }
    int takeStep = minCostClimbingStairs(cost, index + 1, dp) + cost[index];
    int skipStep = minCostClimbingStairs(cost, index + 2, dp);
    dp[index] = Math.min(takeStep, skipStep);
    return dp[index];
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length <= 1) {
        return 0;
    }
    int n = cost.length;
    return minCost(cost, 0, n-1);
}

private int minCost(int[] cost, int i, int n) {
    if (i > n) {
        return Integer.MAX_VALUE;
    } else if(i == n) {
        return 0;
    } else {
        int cost1 = cost[i] + minCost(cost, i+1, n);
        int cost2 = cost[i] + minCost(cost, i+2, n);
        return Math.min(cost1, cost2);
    }
}

