public int uniqueMorseRepresentations(String[] words) {
    // Map to store the Morse code for each character
    Map<Character, String> morseCodes = new HashMap<>();
    morseCodes.put('a', ".-");
    morseCodes.put('b', "-...");
    morseCodes.put('c', "-.-.");
    morseCodes.put('d', "-..");
    morseCodes.put('e', ".");
    morseCodes.put('f', "..-.");
    morseCodes.put('g', "--.");
    morseCodes.put('h', "....");
    morseCodes.put('i', "..");
    morseCodes.put('j', ".---");
    morseCodes.put('k', "-.-");
    morseCodes.put('l', ".-..");
    morseCodes.put('m', "--");
    morseCodes.put('n', "-.");
    morseCodes.put('o', "---");
    morseCodes.put('p', ".--.");
    morseCodes.put('q', "--.-");
    morseCodes.put('r', ".-.");
    morseCodes.put('s', "...");
    morseCodes.put('t', "-");
    morseCodes.put('u', "..-");
    morseCodes.put('v', "...-");
    morseCodes.put('w', ".--");
    morseCodes.put('x', "-..-");
    morseCodes.put('y', "-.--");
    morseCodes.put('z', "--..");
    morseCodes.put(' ', "");

    // Set to store the unique transformations
    Set<String> transformations = new HashSet<>();

    // Iterate through each word and convert it to its Morse code representation
    for (String word : words) {
        StringBuilder morseCode = new StringBuilder();
        for (char c : word.toCharArray()) {
            String code = morseCodes.get(c);
            if (code != null) {
                morseCode.append(code);
            }
        }
        transformations.add(morseCode.toString());
    }

    return transformations.size();
}
