public class MinInsertions {
    public int minInsertions(String s) {
        // Initialize a stack to keep track of the open brackets
        Stack<Character> stack = new Stack<>();
        char[] chars = s.toCharArray();
        for (int i = 0; i < chars.length; i++) {
            if (chars[i] == '(') {
                // If the current character is '(', push it onto the stack
                stack.push((char)chars[i]);
            } else {
                // If the current character is ')', try to pop the top element
                // of the stack. If the stack is empty, push '(' onto the stack.
                if (stack.isEmpty()) {
                    stack.push('(');
                } else {
                    stack.pop();
                }
            }
        }
        // After looping through the entire string, the stack should contain
        // an equal number of '(' and ')'
        return stack.size();
    }
}
