def minOperations(n):
    # Initialize the array
    arr = [0] * n
    for i in range(n):
        arr[i] = (2 * i) + 1

    # Initialize the minimum number of operations to 0
    min_operations = 0

    # Loop until all elements in arr are equal
    while not all(x == arr[0] for x in arr):
        # Find the first pair of indices where the elements are not equal
        for i in range(n - 1):
            for j in range(i + 1, n):
                if arr[i] != arr[j]:
                    # Increment the minimum number of operations
                    min_operations += 1

                    # Select two indices x and y (0 <= x, y < n) and subtract 1 from arr[x] and add 1 to arr[y]
                    x, y = i, j
                    arr[x] -= 1
                    arr[y] += 1

                    # Check if all elements in arr are equal
                    if all(x == arr[0] for x in arr):
                        return min_operations

    # Return the minimum number of operations
    return min_operations
