import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public class SquarePermutations {

    public static int squarePermutations(int[] A) {
        List<int[]> permutations = generatePermutations(A);
        return countSquarePermutations(permutations);
    }

    private static List<int[]> generatePermutations(int[] A) {
        List<int[]> permutations = new ArrayList<>();
        generatePermutations(A, 0, permutations);
        return permutations;
    }

    private static void generatePermutations(int[] A, int i, List<int[]> permutations) {
        if (i == A.length - 1) {
            permutations.add(A);
        } else {
            for (int j = i; j < A.length; j++) {
                swap(A, i, j);
                generatePermutations(A, i + 1, permutations);
                swap(A, i, j);
            }
        }
    }

    private static void swap(int[] A, int i, int j) {
        if (i != j) {
            int temp = A[i];
            A[i] = A[j];
            A[j] = temp;
        }
    }

    private static int countSquarePermutations(List<int[]> permutations) {
        int count = 0;
        for (int[] permutation : permutations) {
            if (isSquarePermutation(permutation)) {
                count++;
            }
        }
        return count;
    }

    private static boolean isSquarePermutation(int[] A) {
        for (int i = 0; i < A.length - 1; i++) {
            int sum = A[i] + A[i + 1];
            if (isSquare(sum)) {
                return true;
            }
        }
        return false;
    }

    private static boolean isSquare(int n) {
        int root = (int) Math.sqrt(n);
        return root * root == n;
    }

    public static void main(String[] args) {
        int[] A = {1, 17, 8};
        int count = squarePermutations(A);
        System.out.println("Number of square permutations of A: " + count);

        A = new int[]{2, 2, 2};
        count = squarePermutations(A);
        System.out.println("Number of square permutations of A: " + count);
    }
}

