/**
     * Calculates the number of square permutations of a given non-negative
     * integer array.
     *
     * @param A the non-negative integer array.
     * @return the number of square permutations of A.
     */
    public static int squarePermutations(int[] A) {
        // Initialize the result variable.
        int result = 0;

        // Get the sum of each pair of adjacent elements in A.
        int[] sum = new int[A.length - 1];
        for (int i = 0; i < A.length - 1; i++) {
            sum[i] = A[i] + A[i + 1];
        }

        // Check each permutation of A.
        for (int i = 0; i < A.length; i++) {
            // If the sum of the current element and the next element is a perfect
            // square, then we found a square permutation.
            if (isPerfectSquare(sum[i])) {
                result++;
            }
            // Rotate the array by one position.
            int temp = A[0];
            for (int j = 1; j < A.length; j++) {
                A[j - 1] = A[j];
            }
            A[A.length - 1] = temp;
        }

        return result;
    }

    /**
     * Checks if the given number is a perfect square.
     *
     * @param x the number to be checked.
     * @return true if x is a perfect square, false otherwise.
     */
    public static boolean isPerfectSquare(int x) {
        int sqrt = (int) Math.sqrt(x);
        return (sqrt * sqrt == x);
    }
