            for (int j = 0; j < squaredArray.length - 1; j++) {
                if (squaredArray[j] != squaredArray[j + 1]) {
                    isSquare = false;
                    break;
                }
            }
            if (isSquare) {
                count++;
            }
        }
        return count;
    }
}
