import java.util.Arrays;

public class LargestRectangleArea {
    public static int largestRectangleArea(int[] heights) {
        // Validate input
        if (heights == null || heights.length == 0) {
            return 0;
        }

        // Initialize variables
        int n = heights.length;
        int maxArea = 0;
        int[] left = new int[n];
        int[] right = new int[n];

        // Build the left and right arrays
        left[0] = 0;
        right[n - 1] = 0;
        for (int i = 1; i < n; i++) {
            if (heights[i - 1] >= heights[i]) {
                left[i] = left[i - 1] + 1;
            } else {
                left[i] = 0;
            }
        }
        for (int i = n - 2; i >= 0; i--) {
            if (heights[i] >= heights[i + 1]) {
                right[i] = right[i + 1] + 1;
            } else {
                right[i] = 0;
            }
        }

        // Calculate the maximum area
        for (int i = 0; i < n; i++) {
            maxArea = Math.max(maxArea, heights[i] * (left[i] + right[i] + 1));
        }

        return maxArea;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(largestRectangleArea(new int[]{2, 1, 5, 6, 2, 3})); // 10
        System.out.println(largestRectangleArea(new int[]{2, 4})); // 4
    }
}
```
This solution uses the concept of "Stacks" to find the maximum rectangle area in a bar chart. The algorithm builds two arrays, `left` and `right`, which represent the distance from the current index to the next smaller element on the left and right, respectively. Then, it calculates the maximum area by finding the element with the largest width and multiplying it by the sum of its left and right distances plus one.

The time complexity of this solution is O(n), and the space complexity is O(n).

public class LargestRectangleArea {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.println("Enter the heights of bars:");
        String[] str = scanner.nextLine().split(" ");
        int[] heights = new int[str.length];
        for (int i = 0; i < heights.length; i++) {
            heights[i] = Integer.parseInt(str[i]);
        }
        System.out.println("The largest rectangle area is: " + largestRectangleArea(heights));
        scanner.close();
    }

    public static int largestRectangleArea(int[] heights) {
        if (heights.length == 0) {
            return 0;
        }
        int result = 0;
        int currentArea = 0;
        Stack<Integer> stack = new Stack<Integer>();
        for (int i = 0; i < heights.length; i++) {
            if (stack.empty()) {
                stack.push(i);
                currentArea = heights[i];
            } else {
                if (heights[i] > heights[stack.peek()]) {
                    currentArea = heights[i] * (i - stack.peek());
                    stack.add(i);
                } else {
                    while (!stack.empty() && heights[i] < heights[stack.peek()]) {
                        int top = stack.pop();
                        int area = heights[top] * (i - stack.peek());
                        currentArea = Math.max(currentArea, area);
                    }
                    stack.add(i);
                }
            }
        }
        while (!stack.empty()) {
            int top = stack.pop();
            int area = heights[top] * (heights.length - stack.peek());
            currentArea = Math.max(currentArea, area);
        }
        result = Math.max(currentArea, result);
        return result;
    }
}

