public static int findSmallestInteger(int n) {
    // Convert the integer to a string and store the digits in an array
    String[] digits = Integer.toString(n).split("");
    Arrays.sort(digits);

    // Build the smallest integer possible by concatenating the sorted digits
    int smallestInteger = Integer.parseInt(String.join("", digits));

    // If the smallest integer is greater than the input integer, return it
    if (smallestInteger > n) {
        return smallestInteger;
    } else {
        // Otherwise, return -1 to indicate that no rearranged integer greater than n was found
        return -1;
    }
