import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.PriorityQueue;

public class MinPerfectSquareSum {

    public static int minPerfectSquareSum(int n) {
        Map<Integer, Integer> squares = new HashMap<>();
        PriorityQueue<Integer> queue = new PriorityQueue<>();

        int[] perfectSquares = {1, 4, 9, 16, 25, 36, 49, 64, 81};
        for (int i = 0; i < perfectSquares.length; i++) {
            squares.put(perfectSquares[i], i);
        }

        int count = 0;
        while (n > 0) {
            int sqrt = squares.get(n);
            if (sqrt == 0) {
                count++;
                n -= squares.get(perfectSquares[perfectSquares.length - 1]);
            } else {
                count++;
                n -= perfectSquares[sqrt];
            }
        }

        return count;
    }

    public static void main(String[] args) {
        int n = 12;
        System.out.println(minPerfectSquareSum(n));
    }
}
```

Note: The above solution first creates a map `squares` to efficiently find the closest perfect square number to the input `n`. Then, it uses a priority queue to store the closest perfect square numbers to the target `n`. The priority queue is constructed such that the smallest perfect square number is at the front of the queue.

The solution then iteratively subtracts the perfect square numbers from the priority queue from the target `n`, and maintains a counter of the number of perfect square numbers used. Once the target `n` becomes less than or equal to zero, the counter indicates the minimum number of perfect square numbers needed to sum up to the target `n`.

```
import java.util.ArrayList;
import java.util.List;

public class MinPerfectSquareSum {
    public static int minPerfectSquareSum(int n) {
        List<Integer> perfectSquares = new ArrayList<>();
        int i = 1;
        while (i * i <= n) {
            perfectSquares.add(i * i);
            i++;
        }
        return dfs(perfectSquares, 0, n, 0);
    }

    private static int dfs(List<Integer> perfectSquares, int current, int target, int count) {
        if (current == target) {
            return count;
        }
        if (current > target) {
            return Integer.MAX_VALUE;
        }
        int minCount = Integer.MAX_VALUE;
        for (Integer perfectSquare : perfectSquares) {
            int newCount = dfs(perfectSquares, current + perfectSquare, target, count + 1);
            minCount = Math.min(newCount, minCount);
            if (minCount == 1) {
                break;
            }
        }
        return minCount;
    }
}
